 */
public class Educational {
    public static void main(String[] args) throws IOException {
        Educational c = new Educational();
        c.start();
    }

    private void start() throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer str = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(str.nextToken());
        String s = in.readLine();
        int b[] = new int[n];
        TreeMap<Integer, Set<Integer>> w = new TreeMap<Integer, Set<Integer>>();


        str = new StringTokenizer(in.readLine());
        for (int i = 0; i < n; ++i) {
            b[i] = Integer.parseInt(str.nextToken());
        }
        char[] res = s.toCharArray();


        HashSet<Integer> waitingList = new HashSet<Integer>();
        for (int i = 0; i < n / 2; ++i) {
            if (res[i] == res[getvisavis(n, i)]) {
                if (waitingList.isEmpty()) {
                    waitingList.add(i);
                } else {
                    boolean found = false;
                    for (Integer j : waitingList) {
                        if (res[j] != res[i]) {
                            int minB1 = b[j] < b[getvisavis(n, j)] ? j : getvisavis(n, j);
                            int minB2 = b[i] < b[getvisavis(n, i)] ? i : getvisavis(n, i);
                            swap(res, minB1, minB2);
                            b[minB1] = 0;
                            b[minB2] = 0;
                            waitingList.remove(j);
                            found = true;
                            break;
                        }
                    }
                    if (! found) waitingList.add(i);
                }
            }
        }
        for (int i = 0; i < n / 2; ++i) {
            if (res[i] == res[getvisavis(n, i)]) {
               // System.out.println(res[i]);
            }
        }


        w.put(0, new HashSet<Integer>());
        for (int i = 0; i < n; ++i) {
          //  if (b[i] == 0) continue;
            if (!w.containsKey(b[i])) w.put(b[i], new HashSet<Integer>());
            w.get(b[i]).add(i);
        }


        for (int i = 0; i < n / 2; ++i) {
            if (res[i] == res[getvisavis(n, i)]) {

                boolean finished = false;

                int indexToChange = b[i] < b[getvisavis(n, i)] ? i : getvisavis(n, i);

                for (Map.Entry<Integer, Set<Integer>> l : w.entrySet()) {
                    Set<Integer> candidates = l.getValue();
                    for (Integer j : candidates) {
                        if (j == i || j == indexToChange || res[indexToChange] == res[j] || res[indexToChange] == res[getvisavis(n, j)]) {
                            continue;
                        }

                        swap(res, indexToChange, j);

                        b[j] = 0;
                        b[indexToChange] = 0;

                        w.get(0).add(j);
                        w.get(0).add(indexToChange);

                        w.get(b[indexToChange]).remove(indexToChange);
                        w.get(b[j]).remove(j);

                        finished = true;
                        break;
                    }

                    if (finished) break;
                }
                if (res[i] == res[getvisavis(n, i)]) System.out.println("alarma");
            }
        }
        for (int i = 0; i < n / 2; ++i) {
            if (res[i] == res[getvisavis(n, i)]) {
                System.out.println("FFFF");
            }
        }


        int sum = 0;
        for (int i = 0; i < n; ++i) {
            //if (!changed[i]) {
            sum += b[i];
            // }
        }

        System.out.println(sum);
    }

    public static int getvisavis(int n, int i) {
        return n - i - 1;
    }

    public static void swap(char[] a, int i, int j) {
        char t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
